def write_font_fixture(path: Path, name: str) -> None:
    """Write a fixed, decodable KaTeX font fixture without host dependencies."""
    write_binary(path, base64.b64decode(FONT_FIXTURES[name]))


def mime_type(path: Path) -> str:
    suffix = path.suffix.lower()
    return {
        ".html": "text/html", ".css": "text/css", ".js": "application/javascript",
        ".map": "application/json", ".jpg": "image/jpeg", ".png": "image/png",
        ".gif": "image/gif", ".webp": "image/webp", ".avif": "image/avif",
        ".jxl": "image/jxl", ".svg": "image/svg+xml", ".woff": "font/woff",
        ".woff2": "font/woff2", ".bin": "application/octet-stream",
    }.get(suffix, "application/octet-stream")


def corpus_manifest(root: Path, seed: str, categories: dict[str, list[str]], capabilities: list[str], edges: list[str]) -> dict[str, Any]:
    files = []
    for path in sorted(current for current in root.rglob("*") if current.is_file() and current.name != "manifest.json"):
        relative = path.relative_to(root).as_posix()
        files.append({"path": relative, "mime_type": mime_type(path), "bytes": path.stat().st_size,
                      "sha256": hashlib.sha256(path.read_bytes()).hexdigest()})
    return {"schema": MANIFEST_SCHEMA, "seed": seed, "files": files, "categories": categories,
            "capabilities": capabilities, "edges": edges}


def write_animated_gif(path: Path) -> None:
    """Write a deterministic two-frame animated GIF without another tool dependency."""
    path.write_bytes(base64.b64decode(
        "R0lGODlhAgACAPAAADQ0NAAAACH/C05FVFNDQVBFMi4wAwEAAAAh+QQAAAAAACwAAAAAAgACAAAC"
        "AoRRACH5BAAKAAAALAAAAAACAAIAgP///wAAAAIChFEAOw=="
    ))


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", required=True, type=Path)
    parser.add_argument("--seed", default="laghu-performance-v1")
    args = parser.parse_args()
    root = args.output
    root.mkdir(parents=True, exist_ok=True)
    categories: dict[str, list[str]] = {}
    capabilities = ["normal", "webp", "avif", "save-data", "dpr-1x", "dpr-2x", "mobile", "tablet", "desktop"]
    edges = ["empty", "no-store", "hashed-url", "huge-query", "malformed-html", "mixed-content", "non-utf8"]
    sizes = {"1k": 1024, "10k": 10 * 1024, "100k": 100 * 1024, "1m": 1024 * 1024, "5m": 5 * 1024 * 1024}
    for name, size in sizes.items():
        write_sized(root / f"html-{name}.html", "<!doctype html><main><!-- removable --> seeded benchmark content</main>", size)
    html_cases = {
        "html-sparse.html": "<!doctype html><main>minimal corpus page</main>",
        "html-assets.html": (
            "<!doctype html><link rel=stylesheet href=/corpus/css/url-heavy.css>"
            "<img src=/image-logo.jpg width=1440 height=1080><script src=/corpus/js/classic.js></script>"
        ),
        "html-inline-css.html": "<!doctype html><style>.card{color:#345;margin:0}</style><main class=card>inline CSS</main>",
        "html-inline-js.html": "<!doctype html><main id=x>inline JS</main><script>document.getElementById('x').dataset.ready='1'</script>",
        "html-comments.html": "<!doctype html><!-- removable --><!-- retained contract --><main>comments</main>",
        "html-deep.html": "<!doctype html>" + "<div>" * 256 + "deep" + "</div>" * 256,
    }
    for name, body in html_cases.items(): write_text(root / "corpus" / "html" / name, body)
    categories["html"] = [f"corpus/html/{name}" for name in html_cases]
    for name, size in {"1k": 1024, "10k": 10 * 1024, "100k": 100 * 1024, "1m": 1024 * 1024, "2m": 2 * 1024 * 1024}.items():
        write_sized(root / f"css-{name}.css", ".card { color: #334455; margin: 0 0 0 0; }", size)
    css_cases = {
        "import-heavy.css": "@import url('/corpus/css/imported.css');.imported{padding:0}",
        "imported.css": ".imported{color:#345}",
        "url-heavy.css": ".a{background:url('/image-icon.jpg')}.b{src:url('/corpus/fonts/subset.woff2')}",
        "unused-rule-heavy.css": ".unused{margin:0}" * 512 + ".used{color:#345}",
        "pre-minified.css": ".card{color:#345;margin:0;padding:0}",
        "framework-scale.css": ".grid{display:grid}" * 32768,
    }
    for name, body in css_cases.items(): write_text(root / "corpus" / "css" / name, body)
    categories["css"] = [f"corpus/css/{name}" for name in css_cases]
    for name, size in {"1k": 1024, "10k": 10 * 1024, "100k": 100 * 1024, "1m": 1024 * 1024, "2m": 2 * 1024 * 1024}.items():
        write_javascript(root / f"js-{name}.js", size)
    javascript_cases = {
        "minified.js": "(()=>{window.laghuMinified=1})();",
        "classic.js": "window.laghuClassic=(window.laghuClassic||0)+1;",
        "blocking.js": "document.documentElement.dataset.blocking='1';",
        "deferred.js": "document.documentElement.dataset.deferred='1';",
        "module.mjs": "export const laghuModule='deterministic';",
        "source-mapped.js": "window.laghuMapped=1;\n//# sourceMappingURL=source-mapped.js.map\n",
    }
    for name, body in javascript_cases.items(): write_text(root / "corpus" / "js" / name, body)
    write_text(root / "corpus" / "js" / "source-mapped.js.map", '{"version":3,"sources":["source-mapped.js"],"names":[],"mappings":"AAAA"}')
    categories["javascript"] = [f"corpus/js/{name}" for name in javascript_cases]
    write_sized(
        root / "no-store.html",
        "<!doctype html><!-- removable --><main>no store</main>",
        1024,
    )
    write_sized(root / "private.html", "<!doctype html><!-- removable --><main>private</main>", 1024)
    write_binary(root / "empty.bin", b"")
    write_text(root / "assets" / "app.0123456789abcdef.css", ".hashed{color:#345}")
    write_text(root / "malformed.html", "<!doctype html><main><img src=/image-480.jpg><div><p>unterminated")
    write_text(root / "mixed-content.html", "<!doctype html><img src=http://insecure.invalid/image.jpg width=1 height=1>")
    write_binary(root / "non-utf8.bin", b"\xff\xfe\x00Laghu\x80")
    write_text(root / "huge-query.html", "<!doctype html><title>large request target</title>")
    categories["edges"] = ["empty.bin", "no-store.html", "assets/app.0123456789abcdef.css", "huge-query.html",
                           "malformed.html", "mixed-content.html", "non-utf8.bin"]
    write_sized(root / "cold.html", "<!doctype html><!-- removable --><main>cold</main>", 1024)
    (root / "never-optimized").mkdir(exist_ok=True)
    write_sized(root / "never-optimized/excluded.html", "<!doctype html><!-- removable --><main>excluded</main>", 1024)
    (root / "index.html").write_text(
        "<!doctype html><html><head><link rel=stylesheet href=/css-10k.css></head><body><h1>Laghu benchmark</h1>"
        "<!-- removable --><img src=/image-480.png width=480 height=320><script src=/js-10k.js></script></body></html>", encoding="utf-8"
    )
    interaction = (
        "<button id=laghu-interaction>Measure interaction</button><script>"
        "window.laghuInteractionDuration=0;new PerformanceObserver(function(list){for(const entry of list.getEntries())"
        "window.laghuInteractionDuration=Math.max(window.laghuInteractionDuration,entry.duration)}).observe("
        "{type:'event',durationThreshold:0});"
        "document.getElementById('laghu-interaction').onclick=function(){let start=performance.now(),end=start+20;"
        "while(performance.now()<end){}window.laghuInteractionDuration=performance.now()-start}</script>"
    )
    fixtures = {
        "cwv-image.html": "<img src=/image-1440.jpg width=1440 height=1080 fetchpriority=high>"
        "<img src=/image-480.png width=480 height=360 loading=lazy>",
        "cwv-css-js.html": "<link rel=stylesheet href=/css-100k.css><script src=/js-100k.js></script>"
        "<main class=card>CSS and JavaScript</main>",
        "cwv-mixed.html": "<link rel=stylesheet href=/css-10k.css><img src=/image-768.png width=768 height=576>"
        "<script src=/js-10k.js></script><main>Mixed page</main>",
    }
    for name, body in fixtures.items():
        document = f"<!doctype html><html><head><title>Laghu CWV</title></head><body>{body}{interaction}</body></html>"
        (root / name).write_text(document, encoding="utf-8")
    (root / "normalized-image.html").write_text(
        "<!doctype html><img src=/image-480.jpg width=480 height=360>", encoding="utf-8"
    )
    dimensions = (100, 480, 768, 1440, 3840, 8000)
    formats = (".png", ".jpg", ".webp", ".avif", ".jxl")
    unavailable_formats: set[str] = set()
    for width in dimensions:
        height = max(1, width * 3 // 4)
        for suffix in formats:
            if not run_vips(root / f"image-{width}{suffix}", width, height, suffix):
                unavailable_formats.add(suffix)
    for content_class in ("photo", "screenshot", "illustration", "flat-color"):
        if not run_class_vips(root / f"image-{content_class}.jpg", content_class):
            raise RuntimeError(f"could not generate {content_class} corpus image")
    if not write_noisy_jpeg(root / "image-noisy.jpg"):
        raise RuntimeError("could not generate noisy corpus image")
    if not run_class_vips(root / "image-logo.jpg", "flat-color") or not run_class_vips(root / "image-icon.jpg", "illustration"):
        raise RuntimeError("could not generate logo/icon corpus images")
    if not run_vips(root / "image-thumbnail.jpg", 64, 48, ".jpg"):
        raise RuntimeError("could not generate thumbnail corpus image")
    if not write_noisy_png(root / "image-processing-cap.png", 1800, 1800):
        raise RuntimeError("could not generate processing-cap corpus image")
    if not run_vips(
        root / "image-transparent-1440.png", 1440, 1080, ".png", transparent=True
    ):
        unavailable_formats.add(".png")
    svg = ('<svg xmlns="http://www.w3.org/2000/svg" xmlns:inkscape="http://www.inkscape.org/namespaces/inkscape" '
           'width="100" height="100" viewBox="0 0 100 100" inkscape:version="1.3">'
           '<title>Laghu benchmark</title><!-- removable --><metadata>editor-only</metadata>'
           '<rect width="100" height="100" fill="#345"/></svg>')
    (root / "image.svg").write_text(svg, encoding="utf-8")
    write_animated_gif(root / "image-animated.gif")
    for name in FONT_FIXTURES:
        write_font_fixture(root / "corpus" / "fonts" / name, name)
    categories["images"] = ["image-thumbnail.jpg", "image-processing-cap.png", "image-photo.jpg", "image-screenshot.jpg",
                            "image-illustration.jpg", "image-flat-color.jpg", "image-noisy.jpg", "image-transparent-1440.png",
                            "image-logo.jpg", "image-icon.jpg"]
    categories["fonts"] = ["corpus/fonts/subset.woff", "corpus/fonts/full.woff2", "corpus/fonts/icons.woff2"]
    manifest = corpus_manifest(root, args.seed, categories, capabilities, edges)
    manifest["images"] = dimensions
    manifest["unavailable_formats"] = sorted(unavailable_formats)
    (root / "manifest.json").write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
